// Endpoint guard chain: auth → validate → idempotency → gate → execute → audit
function guardChain(req, tool) {
  const steps = [];
  if (!req.principal) return { ok: false, at: "auth", status: 401 };
  const bad = tool.validate(req.body);
  if (bad.length) return { ok: false, at: "validate", status: 400, bad };
  if (tool.money && !req.body.idempotencyKey) return { ok: false, at: "key", status: 400 };
  if (tool.gated && !req.approvalRef) return { ok: false, at: "gate", status: 403 };
  return { ok: true };
}
// Order matters: auth before validation (no oracle for attackers), keys before gates.

