  if (!req.principal) return { ok: false, at: 'auth' };
  if (tool.money && !(req.body || {}).idempotencyKey) return { ok: false, at: 'key' };
  if (tool.gated && !req.approvalRef) return { ok: false, at: 'gate' };
  return { ok: true, at: 'ok' };
}
const moneyTool = { money: true, gated: true };
const readTool = { money: false, gated: false };
