  [{}, moneyTool],
  [{ principal: 1, body: {} }, moneyTool],
  [{ principal: 1, body: { idempotencyKey: 'k' } }, moneyTool],
  [{ principal: 1, body: {}, approvalRef: 'a' }, moneyTool],
  [{ principal: 1, body: {} }, readTool],
];
for (const [req, tool] of cases) console.log(guardChain(req, tool).at);

